import React, { useEffect, useRef, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import './Simulador.css';

// Configurar íconos de Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

// Ícono personalizado para aviones
const planeIcon = new L.Icon({
  iconUrl: 'data:image/svg+xml;base64,' + btoa(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#ff8c00" width="24" height="24">
      <path d="M20.56 3.44c.59-.59.59-1.54 0-2.12s-1.54-.59-2.12 0L12 7.76 5.56 1.32c-.59-.59-1.54-.59-2.12 0s-.59 1.54 0 2.12L9.88 9.88 2 12l1.5 1.5 5.5-1.5 6.44 6.44c.59.59 1.54.59 2.12 0s.59-1.54 0-2.12L11.12 9.88l6.44-6.44z"/>
    </svg>
  `),
  iconSize: [24, 24],
  iconAnchor: [12, 12],
  popupAnchor: [0, -12]
});

const Simulador = () => {
  const mapRef = useRef(null);
  const intervalRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(true);
  const [speed, setSpeed] = useState(1);
  const [currentTime, setCurrentTime] = useState('');
  const [elapsedTime, setElapsedTime] = useState('00 : 00 : 00');
  const [currentView, setCurrentView] = useState('flights');
  const [flights, setFlights] = useState([]);
  const [airports, setAirports] = useState([]);
  const [simulationTime, setSimulationTime] = useState(new Date(2024, 7, 27, 8, 0, 0));
  const [startTime] = useState(new Date());

  // Datos de aeropuertos
  const airportsData = [
    { name: 'Lima-Jorge Chávez', code: 'LIM', lat: -12.0219, lng: -77.1143, capacity: 1200, isSede: true, region: 'América del Sur', country: 'Perú' },
    { name: 'Bogotá-El Dorado', code: 'BOG', lat: 4.7016, lng: -74.1469, capacity: 900, region: 'América del Sur', country: 'Colombia' },
    { name: 'Bruselas', code: 'BRU', lat: 50.9010, lng: 4.4844, capacity: 1100, isSede: true, region: 'Europa', country: 'Bélgica' },
    { name: 'Amsterdam-Schiphol', code: 'AMS', lat: 52.3105, lng: 4.7683, capacity: 1200, region: 'Europa', country: 'Países Bajos' },
    { name: 'París-Charles de Gaulle', code: 'CDG', lat: 49.0097, lng: 2.5479, capacity: 1300, region: 'Europa', country: 'Francia' },
    { name: 'Baku-Heydar Aliyev', code: 'GYD', lat: 40.4675, lng: 50.0467, capacity: 1000, isSede: true, region: 'Asia Central', country: 'Azerbaiyán' },
    { name: 'Estambul', code: 'IST', lat: 41.2619, lng: 28.7419, capacity: 1100, region: 'Asia Central', country: 'Turquía' },
    { name: 'Dubai', code: 'DXB', lat: 25.2532, lng: 55.3657, capacity: 1200, region: 'Asia Central', country: 'EAU' },
    { name: 'Madrid-Barajas', code: 'MAD', lat: 40.4983, lng: -3.5676, capacity: 900, region: 'Europa', country: 'España' },
    { name: 'México City', code: 'MEX', lat: 19.4363, lng: -99.0721, capacity: 800, region: 'América del Norte', country: 'México' }
  ];

  // Generar vuelos iniciales
  const generateFlights = () => {
    const newFlights = [];
    const flightTypes = ['MP', 'PACK'];

    for (let i = 0; i < 15; i++) {
      const origin = airportsData[Math.floor(Math.random() * airportsData.length)];
      let destination = airportsData[Math.floor(Math.random() * airportsData.length)];

      while (destination.code === origin.code) {
        destination = airportsData[Math.floor(Math.random() * airportsData.length)];
      }

      const flight = {
        id: `MP${String(i + 1000).padStart(4, '0')}`,
        type: flightTypes[Math.floor(Math.random() * flightTypes.length)],
        origin: origin,
        destination: destination,
        departure: new Date(simulationTime.getTime() + Math.random() * 12 * 60 * 60 * 1000),
        capacity: Math.floor(Math.random() * 200) + 100,
        currentLat: origin.lat,
        currentLng: origin.lng,
        progress: Math.random() * 0.8, // Algunos vuelos ya están en progreso
        status: Math.random() > 0.6 ? 'in-flight' : 'scheduled'
      };

      // Calcular posición actual basada en el progreso
      if (flight.status === 'in-flight') {
        flight.currentLat = flight.origin.lat + (flight.destination.lat - flight.origin.lat) * flight.progress;
        flight.currentLng = flight.origin.lng + (flight.destination.lng - flight.origin.lng) * flight.progress;
      }

      newFlights.push(flight);
    }

    return newFlights;
  };

  useEffect(() => {
    // Inicializar datos
    setAirports(airportsData);
    setFlights(generateFlights());

    // Iniciar simulación
    startSimulation();

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  const startSimulation = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }

    intervalRef.current = setInterval(() => {
      if (isPlaying) {
        updateSimulation();
        updateTime();
      }
    }, 1000);
  };

  const updateSimulation = () => {
    setFlights(prevFlights => {
      return prevFlights.map(flight => {
        const newFlight = { ...flight };

        // Actualizar tiempo de simulación
        const newSimTime = new Date(simulationTime.getTime() + (speed * 60000));

        if (newFlight.status === 'scheduled' && newFlight.departure <= newSimTime) {
          newFlight.status = 'in-flight';
          newFlight.progress = 0;
        }

        if (newFlight.status === 'in-flight') {
          newFlight.progress += 0.005 * speed; // Velocidad de vuelo

          if (newFlight.progress >= 1) {
            newFlight.progress = 1;
            newFlight.status = 'arrived';
            newFlight.currentLat = newFlight.destination.lat;
            newFlight.currentLng = newFlight.destination.lng;
          } else {
            // Interpolar posición
            newFlight.currentLat = newFlight.origin.lat + (newFlight.destination.lat - newFlight.origin.lat) * newFlight.progress;
            newFlight.currentLng = newFlight.origin.lng + (newFlight.destination.lng - newFlight.origin.lng) * newFlight.progress;
          }
        }

        return newFlight;
      });
    });

    // Actualizar tiempo de simulación
    setSimulationTime(prev => new Date(prev.getTime() + (speed * 60000)));
  };

  const updateTime = () => {
    setCurrentTime(simulationTime.toLocaleString());

    const elapsed = Date.now() - startTime.getTime();
    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    setElapsedTime(`${String(hours).padStart(2, '0')} : ${String(minutes).padStart(2, '0')} : ${String(seconds).padStart(2, '0')}`);
  };

  const handlePlay = () => {
    if (simulationRef.current) {
      simulationRef.current.play();
      setIsPlaying(true);
    }
  };

  const handlePause = () => {
    if (simulationRef.current) {
      simulationRef.current.pause();
      setIsPlaying(false);
    }
  };

  const handleStop = () => {
    if (simulationRef.current) {
      simulationRef.current.stop();
      setIsPlaying(false);
    }
  };

  const handleSpeedChange = () => {
    const speeds = [1, 2, 4, 8];
    const currentIndex = speeds.indexOf(speed);
    const nextSpeed = speeds[(currentIndex + 1) % speeds.length];
    setSpeed(nextSpeed);
    if (simulationRef.current) {
      simulationRef.current.setSpeed(nextSpeed);
    }
  };

  const handleRestart = () => {
    if (simulationRef.current) {
      simulationRef.current.stop();
      setTimeout(() => {
        simulationRef.current.startSimulation();
        setIsPlaying(true);
      }, 100);
    }
  };

  const handleViewChange = (view) => {
    setCurrentView(view);
    // Aquí se puede implementar la lógica para cambiar la vista del mapa
  };

  return (
    <div className="simulador-container">
      {/* Sidebar */}
      <div className="simulation-sidebar">
        <div className="sidebar-header">
          <h3><i className="fas fa-cogs"></i> Modos de Operación</h3>
        </div>
        <div className="sidebar-menu">
          <button className="sidebar-item active">
            <i className="fas fa-broadcast-tower"></i>
            <span>Monitoreo en Tiempo Real</span>
          </button>
          <button className="sidebar-item disabled" disabled>
            <i className="fas fa-calendar-week"></i>
            <span>Simulación Semanal</span>
            <small>Próximamente</small>
          </button>
          <button className="sidebar-item disabled" disabled>
            <i className="fas fa-exclamation-triangle"></i>
            <span>Simulación de Colapso</span>
            <small>Próximamente</small>
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="simulation-main-content">
        <div className="control-panel">
          <h2>Monitoreo en Tiempo Real</h2>
          <div className="status-section">
            <span className="status-label">Estado de la Simulación:</span>
            <span className="status-text">
              {isPlaying ? 'Monitoreo en tiempo real activo' : 'Simulación pausada'}
            </span>
          </div>

          {/* Simulation Controls */}
          <div className="simulation-controls">
            <h3><i className="fas fa-cogs"></i> Simulación</h3>
            <div className="control-buttons">
              <button 
                className="sim-control-btn play-btn" 
                onClick={handlePlay}
                disabled={isPlaying}
              >
                <i className="fas fa-play"></i> Iniciar
              </button>
              <button 
                className="sim-control-btn pause-btn" 
                onClick={handlePause}
                disabled={!isPlaying}
              >
                <i className="fas fa-pause"></i> Pausar
              </button>
              <button 
                className="sim-control-btn stop-btn" 
                onClick={handleStop}
              >
                <i className="fas fa-stop"></i> Detener
              </button>
              <button 
                className="sim-control-btn speed-btn" 
                onClick={handleSpeedChange}
              >
                <i className="fas fa-tachometer-alt"></i> {speed}x
              </button>
              <button 
                className="sim-control-btn restart-btn" 
                onClick={handleRestart}
              >
                <i className="fas fa-redo-alt"></i> Reiniciar Todo
              </button>
            </div>
          </div>
        </div>

        {/* Map Container */}
        <div className="map-container">
          <div className="map-area">
            <div ref={mapRef} className="flight-map"></div>

            {/* Map Controls */}
            <div className="map-controls-bottom">
              <button 
                className={`map-btn vuelos-btn ${currentView === 'flights' ? 'active' : ''}`}
                onClick={() => handleViewChange('flights')}
              >
                <i className="fas fa-plane"></i>
                Vuelos
              </button>
              <button 
                className={`map-btn rutas-btn ${currentView === 'routes' ? 'active' : ''}`}
                onClick={() => handleViewChange('routes')}
              >
                <i className="fas fa-route"></i>
                Rutas
              </button>
              <button 
                className={`map-btn aeropuertos-btn ${currentView === 'airports' ? 'active' : ''}`}
                onClick={() => handleViewChange('airports')}
              >
                <i className="fas fa-map-marker-alt"></i>
                Aeropuertos
              </button>
            </div>
          </div>

          {/* Info Panel */}
          <div className="info-panel">
            <div className="info-header">
              <h3>Información del Sistema</h3>
            </div>

            <div className="time-section">
              <div className="current-time">
                <label>Hora actual:</label>
                <div className="time-display">{currentTime}</div>
              </div>

              <div className="elapsed-time">
                <label>Tiempo transcurrido:</label>
                <div className="time-counter">{elapsedTime}</div>
              </div>
            </div>

            <div className="stats-section">
              <div className="stat-item">
                <span className="stat-label">Vuelos Activos:</span>
                <span className="stat-value">12</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Paquetes en Tránsito:</span>
                <span className="stat-value">2,847</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Aeropuertos Operativos:</span>
                <span className="stat-value">24</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Simulador;
